// 再读写该用户的 disconnect_ip 表记录，最后更新 user.disconnect_ip：字段在锁内重新读取，不用事务外读到的旧值覆盖。
// 锁住用户行并读取最新的 disconnect_ip 与同时在线 IP 数限制（每分钟检查新增限制）。
func (q *Queries) LockUserDisconnect(ctx context.Context, id uint32) (LockUserDisconnectRow, error) {
	row := q.db.QueryRowContext(ctx, lockUserDisconnect, id)
	var i LockUserDisconnectRow
	err := row.Scan(&i.DisconnectIp, &i.NodeConnector)
	return i, err
}

