const replaceUserDisconnectIP = `-- name: ReplaceUserDisconnectIP :execrows
UPDATE ` + "`" + `user` + "`" + ` SET disconnect_ip = ?
WHERE id = ? AND CAST(disconnect_ip AS BINARY) = CAST(? AS BINARY)
`

type ReplaceUserDisconnectIPParams struct {
	NewValue string
	ID       uint32
	OldValue interface{}
}

// 修复 disconnect_ip：只有字段仍是读取时的原文才更新。按字节比较（不按字符排序规则：全角 / 半角、大小写、
// 尾随空格都视为不同），读取后被改动过的跳过。
func (q *Queries) ReplaceUserDisconnectIP(ctx context.Context, arg ReplaceUserDisconnectIPParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, replaceUserDisconnectIP, arg.NewValue, arg.ID, arg.OldValue)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

