const upsertIPOnline = `-- name: UpsertIPOnline :exec
INSERT INTO ip_online (userid, ip, first_seen, last_seen) VALUES (?, ?, ?, ?)
ON DUPLICATE KEY UPDATE
    first_seen = IF(last_seen < ?, VALUES(first_seen), first_seen),
    last_seen = GREATEST(last_seen, VALUES(last_seen))
`

type UpsertIPOnlineParams struct {
	Userid      uint32
	Ip          string
	FirstSeen   int64
	LastSeen    int64
	ResetBefore int64
}

// 更新在线状态：已有记录只更新最后上报时间；上次上报早于 reset_before（离线过久）时重新计算开始时间。
func (q *Queries) UpsertIPOnline(ctx context.Context, arg UpsertIPOnlineParams) error {
	_, err := q.db.ExecContext(ctx, upsertIPOnline,
		arg.Userid,
		arg.Ip,
		arg.FirstSeen,
		arg.LastSeen,
		arg.ResetBefore,
	)
	return err
}
